const parts = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Singapore',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).formatToParts(new Date());

const today = `${parts.find(p => p.type === 'year').value}-${parts.find(p => p.type === 'month').value}-${parts.find(p => p.type === 'day').value}`;

const d = new Date(`${today}T00:00:00+08:00`);
d.setDate(d.getDate() - 30);
const lookback_start_date = d.toISOString().slice(0, 10);

return [{
  json: {
    run_date_sgt: today,
    lookback_start_date
  }
}];

const out = [];

for (const item of $input.all()) {
  if (Array.isArray(item.json)) out.push(...item.json);
  else if (Array.isArray(item.json?.data)) out.push(...item.json.data);
  else if (Array.isArray(item.json?.rows)) out.push(...item.json.rows);
  else out.push(item.json);
}

return [{
  json: {
    run_date_sgt: $('Build Scoring Params').first().json.run_date_sgt,
    lookback_start_date: $('Build Scoring Params').first().json.lookback_start_date,
    price_rows: out
  }
}];

const toNum = v => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const round2 = v => {
  if (v === null || v === undefined || !Number.isFinite(v)) return null;
  return Math.round(v * 100) / 100;
};

const clamp = (v, lo = 0, hi = 100) => Math.max(lo, Math.min(hi, v));

const flatten = items => {
  const out = [];
  for (const item of items) {
    if (Array.isArray(item.json)) out.push(...item.json);
    else if (Array.isArray(item.json?.data)) out.push(...item.json.data);
    else if (Array.isArray(item.json?.rows)) out.push(...item.json.rows);
    else out.push(item.json);
  }
  return out;
};

const runDate = $('Wrap Price Rows').first().json.run_date_sgt;
const priceRows = $('Wrap Price Rows').first().json.price_rows || [];
const quantRows = flatten($input.all());

const quantByTicker = {};
for (const q of quantRows) {
  if (!q || !q.ticker) continue;
  quantByTicker[String(q.ticker).trim().toUpperCase()] = q;
}

const pricesByTicker = {};
for (const p of priceRows) {
  if (!p || !p.ticker || !p.metric_date) continue;
  const ticker = String(p.ticker).trim().toUpperCase();
  if (!pricesByTicker[ticker]) pricesByTicker[ticker] = [];
  pricesByTicker[ticker].push({ ...p, ticker });
}

for (const ticker of Object.keys(pricesByTicker)) {
  pricesByTicker[ticker].sort((a, b) =>
    String(a.metric_date).localeCompare(String(b.metric_date))
  );
}

function calcMomentumScore(dayChangePct) {
  const d = toNum(dayChangePct);
  if (d === null) return null;
  return round2(clamp(50 + d * 5));
}

function calcValuationProxy(latestPrice, ma200) {
  const p = toNum(latestPrice);
  const m = toNum(ma200);
  if (p === null || m === null || m === 0) return null;
  return round2(((p - m) / m) * 100);
}

function proxyToOverheatingScore(valuationProxy) {
  const p = toNum(valuationProxy);
  if (p === null) return null;
  return round2(clamp(50 + p));
}

function reversalScoreFromMomentumChange(change) {
  const c = toNum(change);
  if (c === null) return 50;
  return round2(clamp(50 - c * 2));
}

function signalLabel(score, momentumChange5d, reversalSignal) {
  if (reversalSignal) return 'Reversal Short Candidate';
  if (score === null || score === undefined) return 'No Score';
  if (score >= 75) return 'High AI Risk';
  if (score >= 65) return 'Expensive / Watch for Reversal';
  if (score >= 55) return 'Overvalued but Trend Intact';
  if (score >= 40) return 'Neutral';
  if (score >= 25) return 'Low Risk / Reasonable';
  return 'Potential Value / Depressed';
}

const output = [];

// IMPORTANT:
// Loop over quant rows, not price rows.
// This ensures all 45 FMP quant tickers are scored even if priceRows has fewer tickers.
for (const ticker of Object.keys(quantByTicker)) {
  const q = quantByTicker[ticker] || {};
  const rows = pricesByTicker[ticker] || [];

  const todayRow =
    [...rows].reverse().find(r => r.metric_date === runDate) ||
    rows[rows.length - 1] ||
    {};

  const todayIdx = rows.findIndex(r => r.metric_date === todayRow.metric_date);
  const priorRow = todayIdx >= 5 ? rows[todayIdx - 5] : null;

  const rawMomentum = calcMomentumScore(todayRow.day_change_pct);
  const priorMomentum = priorRow ? calcMomentumScore(priorRow.day_change_pct) : null;

  const momentum = rawMomentum !== null ? rawMomentum : 50;

  const momentumChange5d =
    rawMomentum !== null && priorMomentum !== null
      ? rawMomentum - priorMomentum
      : null;

  const valuationProxy = calcValuationProxy(todayRow.latest_price, todayRow.ma200);
  const rawOverheatingScore = proxyToOverheatingScore(valuationProxy);
  const overheatingScoreFinal = rawOverheatingScore !== null ? rawOverheatingScore : 50;

  const valuationScore = toNum(q.valuation_score);
  const overvaluationRiskRaw = toNum(
    q.overvaluation_risk_score ?? (valuationScore !== null ? 100 - valuationScore : null)
  );

  const overvaluationRiskFinal =
    overvaluationRiskRaw !== null ? overvaluationRiskRaw : 50;

  const fundamentalScore = toNum(q.fundamental_score);
  const growthQualityScore = toNum(q.growth_quality_score);
  const dataQualityScore = toNum(q.data_quality_score);

  const reversalScoreFinal = reversalScoreFromMomentumChange(momentumChange5d);

  const overall = round2(
    overvaluationRiskFinal * 0.70 +
    overheatingScoreFinal * 0.15 +
    reversalScoreFinal * 0.15
  );

  const reversalSignal =
    overall !== null &&
    overall >= 75 &&
    momentumChange5d !== null &&
    momentumChange5d < -5;

  output.push({
    json: {
      run_date_sgt: runDate,
      ticker,
      company_name: todayRow.company_name || q.company_name || null,
      ai_subsector: todayRow.ai_subsector || q.ai_subsector || null,

      latest_price: round2(toNum(todayRow.latest_price)),
      ma200: round2(toNum(todayRow.ma200)),
      day_change_pct: round2(toNum(todayRow.day_change_pct)),

      momentum_score: round2(momentum),
      valuation_proxy: round2(valuationProxy),
      valuation_score: round2(valuationScore),
      fundamental_score: round2(fundamentalScore),
      growth_quality_score: round2(growthQualityScore),

      overvaluation_risk_score: round2(overvaluationRiskFinal),
      overheating_score: round2(overheatingScoreFinal),

      ai_hype_score: null,
      overall_ai_risk_score: overall,

      momentum_change_5d: round2(momentumChange5d),
      reversal_score: round2(reversalScoreFinal),
      reversal_signal: reversalSignal,

      signal_label: signalLabel(overall, momentumChange5d, reversalSignal),
      data_quality_score: round2(dataQualityScore),
      missing_fields: q.missing_fields || null,

      explanation: [
        'Workflow 03 revised for full-universe scoring.',
        'Node now loops over FMP quant tickers, not only price tickers.',
        'Missing price-derived momentum defaults to neutral 50.',
        'Missing price-vs-MA200 overheating defaults to neutral 50.',
        'Missing overvaluation risk defaults to neutral 50.',
        'Score formula: 70% FMP overvaluation risk + 15% price-vs-MA200 overheating + 15% reversal risk.',
        'Reversal signal rule: overall_ai_risk_score >= 75 AND momentum_change_5d < -5.',
        `Momentum change 5 trading days: ${round2(momentumChange5d)}.`,
        `Reversal risk score: ${round2(reversalScoreFinal)}.`,
        `Reversal signal: ${reversalSignal}.`
      ].join(' '),

      source: 'workflow_03_fmp_reversal_filter_v3_full_universe'
    }
  });
}

return output;

return $input.all().map(item => {
  const x = item.json;

  return {
    json: {
      run_date_sgt: x.run_date_sgt,
      ticker: x.ticker,
      momentum_score: x.momentum_score,
      valuation_score: x.valuation_score,
      overheating_score: x.overheating_score,
      ai_hype_score: x.ai_hype_score,
      overall_ai_risk_score: x.overall_ai_risk_score,
      signal_label: x.signal_label,
      explanation: x.explanation,
      momentum_change_5d: x.momentum_change_5d,
      reversal_score: x.reversal_score,
      reversal_signal: x.reversal_signal
    }
  };
});
